import re

def check(call, view, history):
    if getattr(call, 'name', None) != 'run_command':
        return None
    args = getattr(call, 'args', {}) or {}
    cmd = args.get('cmd') or ''
    try:
        calls = int((view or {}).get('calls') or 0)
    except Exception:
        calls = 0
    if calls < 25:
        return None
    if not re.search(r'\bgrep\b', cmd):
        return None
    if not re.search(r'(^|[\s/])gpt2-124M\.ckpt\b|\.ckpt\b', cmd):
        return None
    if re.search(r'\btimeout\s+(?:[1-9]|1[0-5])\b', cmd):
        return None
    return 'Do not launch an unbounded grep over the GPT-2 checkpoint this late in the task; it can consume the remaining time. Use a small bounded probe such as dd/od with count/skip, or wrap the command in a short timeout, then continue fixing the code.'

def check(call, view, history):
    if call.name != 'run_command':
        return None
    calls = view.get('calls')
    if isinstance(calls, int) and calls >= 32:
        return 'The task is already at the late-call budget; do not run another command. Stop debugging now and provide the best final summary based on the current files.'
    return None
